steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        project(name: \"Checkout Redesign\") {
          id
          name
          issues(first: 50) {
            nodes {
              id
              identifier
              title
              priority
              milestone {
                id
                name
                status
                targetDate
              }
            }
          }
        }
      }
    '
  }'
